<script setup>import {ref,onMounted,onUnmounted} from 'vue';import {collection,addDoc,onSnapshot,query,orderBy,serverTimestamp,limit} from 'firebase/firestore';import {db} from '../firebase';import {uploadSmall,addReport} from '../services/data';const props=defineProps(['user','profile']);const emit=defineEmits(['toast']);const text=ref(''),photo=ref(null),messages=ref([]);let stop;onMounted(()=>{stop=onSnapshot(query(collection(db,'chat'),orderBy('createdAt','asc'),limit(200)),s=>messages.value=s.docs.map(d=>({id:d.id,...d.data()})))});onUnmounted(()=>stop?.());async function send(){if(!text.value.trim()&&!photo.value)return;let imageUrl='';if(photo.value)imageUrl=await uploadSmall(props.user.uid,photo.value,'chat');await addDoc(collection(db,'chat'),{uid:props.user.uid,author:props.profile.displayName,text:text.value.trim(),imageUrl,createdAt:serverTimestamp()});text.value='';photo.value=null}async function report(m){await addReport({reporterUid:props.user.uid,targetType:'chat',targetId:m.id,targetUid:m.uid,reason:'Sohbet bildirimi'});emit('toast','Rapor alındı.')} </script><template><h1>Açık Sohbet</h1><div class="card chat-box"><div class="messages"><div v-for="m in messages" :key="m.id" class="message"><div class="space"><b>{{m.author}}</b><button v-if="m.uid!==user.uid" class="btn secondary" @click="report(m)">⚑</button></div><p v-if="m.text">{{m.text}}</p><img v-if="m.imageUrl" :src="m.imageUrl" class="post-image"></div><div v-if="!messages.length" class="empty">Henüz mesaj yok. İlk mesajı sen yaz!</div></div><div class="composer"><input class="field" v-model="text" @keyup.enter="send" maxlength="1000" placeholder="Mesaj yaz..."><input class="field" type="file" accept="image/*" @change="photo=$event.target.files[0]||null"><button class="btn" @click="send">Gönder</button></div></div></template>